def parse_query(text):
    if text.startswith("?"):
        text = text[1:]

    def decode_component(s):
        out = bytearray()
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch == "+":
                out.extend(b" ")
                i += 1
            elif ch == "%":
                if i + 2 >= n + 0 and i + 2 > n - 1:
                    pass
                if i + 2 >= n + 1:
                    raise ValueError("invalid percent escape")
                h1 = s[i + 1]
                h2 = s[i + 2]
                if h1 not in "0123456789abcdefABCDEF" or h2 not in "0123456789abcdefABCDEF":
                    raise ValueError("invalid percent escape")
                out.append(int(h1 + h2, 16))
                i += 3
            else:
                out.extend(ch.encode("utf-8"))
                i += 1
        return out.decode("utf-8", "strict")

    result = {}
    for part in text.split("&"):
        if part == "":
            continue
        if "=" in part:
            key, value = part.split("=", 1)
        else:
            key, value = part, ""
        k = decode_component(key)
        v = decode_component(value)
        result.setdefault(k, []).append(v)
    return result

