def merge_ranges(ranges):
    """Merge overlapping or adjacent half-open integer intervals.

    Each interval is [start, end). Empty intervals (start == end) are ignored.
    Raises ValueError for malformed intervals or non-integer endpoints.
    The input is not modified.
    """
    normalized = []
    for interval in ranges:
        try:
            length = len(interval)
        except TypeError:
            raise ValueError("each interval must be a sequence of two integers")
        if length != 2:
            raise ValueError("each interval must contain exactly two endpoints")
        start, end = interval[0], interval[1]
        if isinstance(start, bool) or isinstance(end, bool):
            raise ValueError("interval endpoints must be integers, not bool")
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("interval endpoints must be integers")
        if start > end:
            raise ValueError("interval start must not exceed end")
        if start == end:
            continue
        normalized.append((start, end))

    normalized.sort()

    merged = []
    for start, end in normalized:
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])

    return merged

