def decode_runs(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    if text == "":
        return ""

    items = []
    i = 0
    n = len(text)

    while True:
        # Parse count: canonical ASCII decimal integer 1..100, no leading zeros
        start = i
        while i < n and '0' <= text[i] <= '9':
            i += 1
        count_str = text[start:i]
        if not count_str:
            raise ValueError("missing count")
        if len(count_str) > 1 and count_str[0] == '0':
            raise ValueError("leading zero in count")
        count = int(count_str)
        if count < 1 or count > 100:
            raise ValueError("count out of range")

        # Expect colon separator
        if i >= n or text[i] != ':':
            raise ValueError("missing colon")
        i += 1

        # Parse exactly one char, handling escapes
        if i >= n:
            raise ValueError("missing char")
        ch = text[i]
        if ch == '\\':
            i += 1
            if i >= n:
                raise ValueError("dangling backslash")
            esc = text[i]
            if esc == ':':
                ch = ':'
            elif esc == ',':
                ch = ','
            elif esc == '\\':
                ch = '\\'
            else:
                raise ValueError("invalid escape")
            i += 1
        elif ch == ':' or ch == ',':
            raise ValueError("unescaped special char")
        else:
            i += 1

        items.append((count, ch))

        # After char, either end of string or a comma separator
        if i >= n:
            break
        if text[i] != ',':
            raise ValueError("unexpected character")
        i += 1
        if i >= n:
            raise ValueError("empty item")

    total = 0
    for count, _ in items:
        total += count
        if total > 1000:
            raise ValueError("output too long")

    return "".join(ch * count for count, ch in items)

